<section><div class="page-heading"><div><p class="eyebrow">Tenants</p><h1>Stores</h1><p class="muted">Inspect tenant usage, publication status, ownership, and subscriptions.</p></div><span><?= e($result['total']) ?> stores</span></div><form class="admin-filters stores" method="get" action="/sa/stores"><input type="search" name="q" value="<?= e($filters['q']) ?>" placeholder="Store, slug, owner, or email" aria-label="Search stores"><select name="status" aria-label="Store status"><option value="">All statuses</option><?php foreach(['DRAFT','ACTIVE','SUSPENDED']as$status):?><option value="<?= e($status) ?>" <?= $filters['status']===$status?'selected':'' ?>><?= e(ucfirst(strtolower($status))) ?></option><?php endforeach ?></select><select name="plan" aria-label="Plan"><option value="">All plans</option><?php foreach($plans as$plan):?><option value="<?= e($plan['code']) ?>" <?= $filters['plan']===$plan['code']?'selected':'' ?>><?= e($plan['name']) ?></option><?php endforeach ?></select><button class="button secondary">Filter</button></form><section class="panel flush"><div class="table-wrap"><table><thead><tr><th>Store</th><th>Owner</th><th>Status</th><th>Plan</th><th>Usage</th><th></th></tr></thead><tbody><?php foreach($result['items']as$row):?><tr><td><strong><?= e($row['name']) ?></strong><small>/<?= e($row['slug']) ?> · <?= e($row['country_code']) ?> / <?= e($row['currency_code']) ?></small></td><td><?php if($row['owner_id']):?><a href="/sa/merchants/<?= e($row['owner_id']) ?>"><?= e($row['owner_name']) ?></a><small><?= e($row['owner_email']) ?></small><?php else:?>No active owner<?php endif ?></td><td><span class="badge <?= strtolower($row['status']) ?>"><?= e($row['status']) ?></span></td><td><?= e($row['plan_name']??'Unconfigured') ?><small><?= e($row['subscription_status']??'') ?></small></td><td><?= e($row['products']) ?> products · <?= e($row['orders']) ?> orders</td><td><a class="button compact secondary" href="/sa/stores/<?= e($row['id']) ?>">Inspect</a></td></tr><?php endforeach ?></tbody></table></div><?php if(!$result['items']):?><div class="empty-inline padded">No stores match these filters.</div><?php endif ?></section><?php $base=['q'=>$filters['q'],'status'=>$filters['status'],'plan'=>$filters['plan']];?><nav class="admin-pagination" aria-label="Store pages"><?php if($result['page']>1):?><a href="?<?= e(http_build_query($base+['page'=>$result['page']-1])) ?>">← Previous</a><?php endif ?><span>Page <?= e($result['page']) ?> of <?= e($result['pages']) ?></span><?php if($result['page']<$result['pages']):?><a href="?<?= e(http_build_query($base+['page'=>$result['page']+1])) ?>">Next →</a><?php endif ?></nav></section>
